# Five programs in one file, each of which repair handles on its own. The
# point of this one is its size: a repair is a whole-file rewrite, so a long
# file has to be restated in a single reply, and this is where that stops
# being free.
#
# Generated by scratchpad/make_omnibus.py - every part is verbatim from the
# corpus except that its main() is renamed and called from the real one.

# ---------------------------------------------- strings
def row(name, count, unit):
    label = name + ":"
    return label + " " + str(count) + " " + unit


def part_strings():
    print(row("apples", 12, "crates"))
    print(row("pears", 7, "boxes"))
    print(row("plums", 103, "bags"))
    total = 12 + 7 + 103
    print("total " + str(total) + " items")
    return 0


# ---------------------------------------------- growing
def collatz_steps(n):
    steps = 0
    while n != 1:
        if n % 2 == 0:
            n //= 2
        else:
            n = 3 * n + 1
        steps += 1
    return steps


def part_growing():
    long_ones = []
    for start in range(2, 40):
        steps = collatz_steps(start)
        if steps > 15:
            long_ones.append(start)

    print("count", len(long_ones))
    print("first three", long_ones[:3])
    print("sorted desc", sorted(long_ones, reverse=True)[:3])
    print("has 27", 27 in long_ones)
    return 0


# ---------------------------------------------- inherit
class Shape:
    def __init__(self, name):
        self.name = name

    def area(self):
        return 0

    def describe(self):
        print(self.name, "area", self.area())


class Square(Shape):
    def __init__(self, side):
        super().__init__("square")
        self.side = side

    def area(self):
        return self.side * self.side


class Rect(Shape):
    def __init__(self, w, h):
        super().__init__("rect")
        self.w = w
        self.h = h

    def area(self):
        return self.w * self.h


def part_inherit():
    shapes = [Square(4), Rect(3, 5), Square(7), Rect(2, 9)]
    for shape in shapes:
        shape.describe()
    biggest = max(shapes, key=lambda s: s.area())
    print("biggest is", biggest.name, biggest.area())
    return 0


# ---------------------------------------------- raising
class TooBig(Exception):
    pass


def checked_double(n):
    if n > 50:
        raise TooBig("%d is too big" % n)
    return n * 2


def part_raising():
    for n in (4, 20, 60, 9):
        try:
            print("doubled", checked_double(n))
        except TooBig:
            print("refused", n)
    print("done")
    return 0


# ---------------------------------------------- mapping
def part_mapping():
    words = ["pear", "fig", "pear", "apple", "fig", "pear", "quince"]

    counts = {}
    for word in words:
        counts[word] = counts.get(word, 0) + 1

    for name, count in sorted(counts.items()):
        print(name, count)

    best = max(counts, key=counts.get)
    print("most common:", best, "with", counts[best])
    return 0



def main() -> int:
    print("== strings")
    part_strings()
    print("== growing")
    part_growing()
    print("== inherit")
    part_inherit()
    print("== raising")
    part_raising()
    print("== mapping")
    part_mapping()
    return 0
